#include <bits/stdc++.h>

using namespace std;

#define inf (long long)1e15
#define ll long long
#define all(x) x.begin(), x.end()
#define x first
#define y second

const int MAXN = 200010;
const int MAX_LIMIT = 1000010;

vector<ll> seq({0ll});
int min_steps_found = MAX_LIMIT;

void explore(ll x, int steps) {
    if (steps > min_steps_found)
        return;
    if (x == 0) {
        min_steps_found = steps;
        return;
    }
    auto start_it = lower_bound(all(seq), x);
    auto end_it = upper_bound(all(seq), x);
    if (start_it == end_it) start_it--;
    ll diff1 = x - *start_it;
    int cost = start_it - seq.begin();
    ll diff2 = *end_it - x;
    explore(x % *start_it, steps + cost * (x / *start_it));
    explore(diff2, steps + cost + 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    ll n;
    cin >> n;
    for (int i = 1; i <= 16; ++i) {
        seq.push_back(seq.back() * 10 + 1);
    }
    explore(n, 0);
    cout << min_steps_found << "\n";
    return 0;
}
